// Issue227 configurable request gap. END_REQ and bounded admission preserved.
// Independent component/state diagnostics; no scheduler changes.
// v6 scatter DMA: generated by prepare_scatter_v6.py
// Persistent JSON-lines bridge. Actual nonblocking 4-phase TLM requests;
// no b_transport constant-delay shortcut and no offline timestamp replay.
#include <DRAMSys/DRAMSys.h>
#include <DRAMSys/common/MemoryManager.h>
#include <DRAMSys/configuration/memspec/MemSpec.h>
#include <DRAMSys/power/DRAMPowerAdapter.h>
#include <DRAMSys/statistics/JsonFormat.h>
#include <tlm_utils/multi_passthrough_initiator_socket.h>
#include <fstream>
#include <array>
#include <tlm_utils/peq_with_cb_and_phase.h>
#include <nlohmann/json.hpp>
#include <iostream>
#include <cmath>
#include <vector>
#include <deque>
#include <unordered_map>
#include <stdexcept>
using json=nlohmann::json;

class Initiator:public sc_core::sc_module {
public:
    tlm_utils::multi_passthrough_initiator_socket<Initiator> socket{"socket"};
    SC_HAS_PROCESS(Initiator);
    Initiator(sc_core::sc_module_name name,std::ostream& output,
              std::uint64_t capacity,unsigned maxPending,unsigned hostBytes=64,unsigned acceptDelayPs=1,unsigned requestGapPs=0,unsigned requestLanes=1):
        sc_module(name),out(output),capacity(capacity),limit(maxPending),hostBytes(hostBytes),acceptDelayPs(acceptDelayPs),requestGapPs(requestGapPs),requestLanes(requestLanes),
        peq(this,&Initiator::phase),mm(false) {
        socket.register_nb_transport_bw(this,&Initiator::backward);
        SC_THREAD(run);
        SC_THREAD(issueAsync);
    }
    std::uint64_t bursts=0,readBursts=0,writeBursts=0,hostTransactions=0;
    unsigned peakPending=0;
    double requestedEnd=0;
private:
    std::ostream& out;
    std::uint64_t capacity;
    unsigned limit,hostBytes,acceptDelayPs,requestGapPs,requestLanes,pending=0;
    std::array<bool,8> requestBusy{};
    std::unordered_map<tlm::tlm_generic_payload*,unsigned> laneOf;
    unsigned lane(std::uint64_t address) const {return requestLanes==1?0:((address>>6)&7);}
    struct Request {std::uint64_t id,address;bool write;};
    std::deque<Request> queued;
    std::unordered_map<tlm::tlm_generic_payload*,std::uint64_t> ids;
    json responses=json::array();
    sc_core::sc_event submitted;
    std::uint64_t lastId=0;
    void issueAsync() {
      while(true) {
        while(queued.empty()) wait(submitted);
        auto it=queued.begin();
        while(it!=queued.end() && requestBusy[lane(it->address)]) ++it;
        if(pending>=limit || it==queued.end()) {wait(endRequest|completed|submitted);continue;}
        auto r=*it;queued.erase(it);auto port=lane(r.address);
        auto* p=mm.allocate(64);p->acquire();ids[p]=r.id;laneOf[p]=port;
        p->set_address(r.address);p->set_data_length(64);p->set_streaming_width(64);
        p->set_command(r.write?tlm::TLM_WRITE_COMMAND:tlm::TLM_READ_COMMAND);
        p->set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);p->set_dmi_allowed(false);
        p->set_byte_enable_ptr(nullptr);p->set_byte_enable_length(0);
        requestBusy[port]=true;++pending;peakPending=std::max(peakPending,pending);
        ++bursts;++hostTransactions;if(r.write)++writeBursts;else ++readBursts;
        tlm::tlm_phase phase=tlm::BEGIN_REQ;auto delay=sc_core::SC_ZERO_TIME;
        if(socket[port]->nb_transport_fw(*p,phase,delay)!=tlm::TLM_ACCEPTED)
          SC_REPORT_FATAL("bridge","unexpected async forward status");
        wait(sc_core::sc_time(requestGapPs,sc_core::SC_PS));
      }
    }
    sc_core::sc_event endRequest,completed;
    tlm_utils::peq_with_cb_and_phase<Initiator> peq;
    DRAMSys::MemoryManager mm;
    tlm::tlm_sync_enum backward(int socketId,tlm::tlm_generic_payload& p,tlm::tlm_phase& phase,
                               sc_core::sc_time& delay) {
        if(laneOf.at(&p)!=static_cast<unsigned>(socketId)) SC_REPORT_FATAL("bridge","wrong response port");
        peq.notify(p,phase,delay);
        return tlm::TLM_ACCEPTED;
    }
    void phase(tlm::tlm_generic_payload& p,const tlm::tlm_phase& phase) {
        if(phase==tlm::END_REQ) {
            requestBusy[laneOf.at(&p)]=false;endRequest.notify(sc_core::SC_ZERO_TIME);
        } else if(phase==tlm::BEGIN_RESP) {
            if(p.is_response_error()) SC_REPORT_FATAL("bridge","memory response error");
            --pending;
            auto it=ids.find(&p);
            if(it!=ids.end()) {
              responses.push_back(json{{"id",it->second},{"done_ns",sc_core::sc_time_stamp().to_seconds()*1e9}});
              ids.erase(it);
            }
            tlm::tlm_phase finish=tlm::END_RESP;
            auto delay=sc_core::sc_time(acceptDelayPs,sc_core::SC_PS);
            socket[laneOf.at(&p)]->nb_transport_fw(p,finish,delay);
            laneOf.erase(&p);
            p.release();completed.notify(sc_core::SC_ZERO_TIME);
        } else SC_REPORT_FATAL("bridge","unexpected backward phase");
    }
    void advance(double ns) {
        auto target=sc_core::sc_time(ns,sc_core::SC_NS);
        if(target>sc_core::sc_time_stamp()) wait(target-sc_core::sc_time_stamp());
    }
    void run() {
        out<<json({{"status","ready"},{"memory_bytes",capacity},
                   {"host_request_bytes",hostBytes},{"request_gap_ps",requestGapPs},{"request_lanes",requestLanes},{"features",json::array({"scatter_gather_v1","aligned_coalescing_v1","bounded_async_v1","request_gap_v1","lane_dma_v1"})}}).dump()<<std::endl;
        std::string line;
        while(std::getline(std::cin,line)) {
            auto r=json::parse(line);
            if(r.at("op")=="step") {
              double horizon=r.at("until_ns");
              if(horizon+1e-6<sc_core::sc_time_stamp().to_seconds()*1e9)
                throw std::runtime_error("async time reversal");
              // Admission is finite: queued plus TLM in-flight <= max_pending.
              unsigned accepted=0;
              for(const auto& x:r.value("requests",json::array())) {
                if(queued.size()+pending>=limit)break;
                std::uint64_t id=x.at("id"),address=x.at("address");
                if(id<=lastId||address%64||address>=capacity||64>capacity-address)
                  throw std::runtime_error("invalid async id/address");
                lastId=id;queued.push_back({id,address,x.value("write",false)});++accepted;
              }
              if(accepted)submitted.notify(sc_core::SC_ZERO_TIME);
              wait(sc_core::SC_ZERO_TIME);
              auto target=sc_core::sc_time(horizon,sc_core::SC_NS);
              if(responses.empty()&&target>sc_core::sc_time_stamp())
                wait(target-sc_core::sc_time_stamp(),completed);
              out<<json{{"status","step"},{"accepted",accepted},{"now_ns",sc_core::sc_time_stamp().to_seconds()*1e9},
                {"responses",responses},{"outstanding",pending+queued.size()}}.dump()<<std::endl;
              responses=json::array();continue;
            }
            if(r.at("op")=="finish") {
                if(!queued.empty()||pending)throw std::runtime_error("finish with outstanding requests");
                requestedEnd=r.at("end_ns").get<double>();
                advance(requestedEnd);
                sc_core::sc_stop();return;
            }
            std::vector<std::pair<std::uint64_t,std::uint64_t>> spans;
            if(r.at("op")=="access") {
                spans.emplace_back(r.at("address").get<std::uint64_t>(),r.at("bytes").get<std::uint64_t>());
            } else if(r.at("op")=="access_sg") {
                for(const auto& span:r.at("ranges"))
                    spans.emplace_back(span.at("address").get<std::uint64_t>(),span.at("bytes").get<std::uint64_t>());
                if(spans.size()>256) throw std::runtime_error("scatter descriptor overflow");
            } else throw std::runtime_error("unknown operation");
            std::uint64_t length=0;
            if(spans.empty()) throw std::runtime_error("empty DMA");
            for(const auto& span:spans) {
                auto address=span.first, size=span.second;
                if(!size||address%64||size%64||address>=capacity||size>capacity-address)
                    throw std::runtime_error("unaligned or out-of-bounds DMA");
                length+=size;
            }
            advance(r.at("ready_ns").get<double>());
            auto start=sc_core::sc_time_stamp();
            bool write=r.at("write").get<bool>();
            for(const auto& span:spans) for(std::uint64_t offset=0;offset<span.second;) {
                auto address=span.first+offset;
                unsigned bytes=hostBytes;
                while(bytes>64 && (address%bytes || bytes>span.second-offset)) bytes/=2;
                auto port=lane(address);
                while(requestBusy[port]) wait(endRequest);
                while(pending>=limit) wait(completed);
                auto* p=mm.allocate(bytes);p->acquire();laneOf[p]=port;
                p->set_address(address);p->set_data_length(bytes);p->set_streaming_width(bytes);
                p->set_command(write?tlm::TLM_WRITE_COMMAND:tlm::TLM_READ_COMMAND);
                p->set_response_status(tlm::TLM_INCOMPLETE_RESPONSE);
                p->set_dmi_allowed(false);p->set_byte_enable_ptr(nullptr);
                p->set_byte_enable_length(0);
                requestBusy[port]=true;++pending;peakPending=std::max(peakPending,pending);
                bursts+=bytes/64;if(write)writeBursts+=bytes/64;else readBursts+=bytes/64;
                ++hostTransactions;offset+=bytes;
                tlm::tlm_phase phase=tlm::BEGIN_REQ;auto delay=sc_core::SC_ZERO_TIME;
                auto status=socket[port]->nb_transport_fw(*p,phase,delay);
                if(status!=tlm::TLM_ACCEPTED) SC_REPORT_FATAL("bridge","unexpected forward status");
                // Optional initiator pacing; real END_REQ/credit/JEDEC limits remain.
                wait(sc_core::sc_time(requestGapPs,sc_core::SC_PS));
            }
            while(pending) wait(completed);
            out<<json({{"id",r.at("id")},{"done_ns",sc_core::sc_time_stamp().to_seconds()*1e9},
                       {"start_ns",start.to_seconds()*1e9},{"burst_count",length/64}}).dump()<<std::endl;
        }
        throw std::runtime_error("EOF without finish");
    }
};

void powerAt(sc_core::sc_object* obj,std::uint64_t cycle,json& energy) {
    if(auto* adapter=dynamic_cast<DRAMSys::DRAMPowerAdapter*>(obj)) {
        // Official adapter's stats use last command time. Evaluate the official
        // DRAMPower API at the full system horizon, including the compute tail.
        auto& variant=const_cast<DRAMSys::DRAMPowerVariant&>(adapter->getDRAMPowerVariant());
        std::visit([&](auto& model) {
            auto stats=model.getWindowStats(cycle);
            auto core=model.calcCoreEnergy(stats);
            auto iface=model.calcInterfaceEnergy(stats);
            // Sum physical-bank contributions only. aggregated_bank_energy()
            // already adds E_bg_act_shared and would double count it below.
            DRAMPower::energy_info_t bank;
            for(const auto& e:core.bank_energy) bank+=e;
            json components={
                {"ACT",bank.E_act},{"PRE",bank.E_pre},
                {"BG_ACT_BANK",bank.E_bg_act},{"BG_ACT_SHARED",core.E_bg_act_shared},
                {"BG_PRE",bank.E_bg_pre},{"RD",bank.E_RD},{"WR",bank.E_WR},
                {"RDA",bank.E_RDA},{"WRA",bank.E_WRA},
                {"REF_AB",bank.E_ref_AB},{"REF_PB",bank.E_ref_PB},
                {"REF_SB",bank.E_ref_SB},{"REF_2B",bank.E_ref_2B},
                {"REF_DB",bank.E_ref_DB},{"PDNA",core.E_PDNA},
                {"PDNP",core.E_PDNP},{"SREF",core.E_sref},
                {"DSM",core.E_dsm},{"REFAB_GLOBAL",core.E_refab}};
            double componentSum=0;
            for(auto& item:components.items()) componentSum+=item.value().get<double>();
            json ranks=json::array(),banks=json::array();
            auto state=[](const auto& item) {
                const auto& c=item.cycles;
                const auto& n=item.counter;
                return json{
                    {"cycles",{{"act",c.act},{"pre",c.pre},
                        {"powerDownAct",c.powerDownAct},{"powerDownPre",c.powerDownPre},
                        {"selfRefresh",c.selfRefresh},{"deepSleepMode",c.deepSleepMode}}},
                    {"commands",{{"ACT",n.act},{"PRE",n.pre},{"RD",n.reads},
                        {"WR",n.writes},{"RDA",n.readAuto},{"WRA",n.writeAuto},
                        {"REF_AB",n.refAllBank},{"REF_PB",n.refPerBank},
                        {"REF_2B",n.refPerTwoBanks},{"REF_DB",n.refDualBanks},
                        {"REF_SB",n.refSameBank}}}};
            };
            for(const auto& rank:stats.rank_total) ranks.push_back(state(rank));
            for(const auto& b:stats.bank) banks.push_back(state(b));
            energy[obj->basename()]={
                {"core_J",core.total()},{"interface_J",iface.total()},
                {"total_J",core.total()+iface.total()},
                {"core_components_J",components},
                {"core_component_sum_J",componentSum},
                {"core_component_residual_J",core.total()-componentSum},
                {"interface_components_J",{
                    {"controller_dynamic",iface.controller.dynamicEnergy},
                    {"controller_static",iface.controller.staticEnergy},
                    {"dram_dynamic",iface.dram.dynamicEnergy},
                    {"dram_static",iface.dram.staticEnergy}}},
                {"rank_stats",ranks},{"bank_stats",banks},
                {"audit_version","drampower-6.3.1-components-v1"}};
        },variant);
    }
    for(auto* child:obj->get_child_objects()) powerAt(child,cycle,energy);
}

int sc_main(int argc,char** argv) {
    try {
        if(argc<3 || argc>7) throw std::runtime_error("usage: bridge configuration.json max_pending [host_request_bytes [response_accept_delay_ps [request_gap_ps [request_lanes]]]]");
        sc_core::sc_set_time_resolution(1,sc_core::SC_PS);
        std::ostream output(std::cout.rdbuf());
        std::cout.rdbuf(std::cerr.rdbuf()); // upstream logs never pollute JSON protocol
        auto config=DRAMSys::Config::from_path(argv[1]);
        DRAMSys::DRAMSys dram("dram",config);
        auto limit=std::stoul(argv[2]);
        if(!limit) throw std::runtime_error("max_pending must be positive");
        auto hostBytes=argc>=4?std::stoul(argv[3]):64;
        if(hostBytes!=64 && hostBytes!=256) throw std::runtime_error("host_request_bytes must be 64 or 256");
        auto acceptDelayPs=argc>=5?std::stoul(argv[4]):1;
        if(acceptDelayPs>1) throw std::runtime_error("response accept delay must be 0 or 1 ps");
        auto requestGapPs=argc>=6?std::stoul(argv[5]):0;
        auto requestLanes=argc>=7?std::stoul(argv[6]):1;
        if(requestLanes!=1 && requestLanes!=8) throw std::runtime_error("request_lanes must be1 or8");
        if(requestLanes==8) {
            std::ifstream input(argv[1]);auto j=json::parse(input).at("simulation");
            if(j.at("addressmapping").at("CHANNEL_BIT")!=json::array({6,7,8}) ||
               j.at("memspec").at("memarchitecturespec").at("nbrOfChannels")!=8 || hostBytes!=64)
                throw std::runtime_error("8lane bridge requires8channel mapping bits6,7,8 and64B requests");
        }
        Initiator initiator("dma",output,dram.memorySize(),limit,hostBytes,acceptDelayPs,requestGapPs,requestLanes);
        for(unsigned port=0;port<requestLanes;++port)initiator.socket.bind(dram.tSocket);
        sc_core::sc_start();
        json stats,energy;
        DRAMSys::Stats::JsonFormat::collectStats(&dram,stats);
        auto cycle=static_cast<std::uint64_t>(std::floor(sc_core::sc_time_stamp()/dram.getMemSpec().tCK));
        powerAt(&dram,cycle,energy);
        output<<json({{"status","finished"},{"stats",stats},{"power_at_system_end",energy},
            {"end_ns",sc_core::sc_time_stamp().to_seconds()*1e9},{"dram_end_cycle",cycle},
            {"burst_count",initiator.bursts},{"host_transactions",initiator.hostTransactions},
            {"host_request_bytes",hostBytes},{"request_gap_ps",requestGapPs},{"request_lanes",requestLanes},{"response_accept_delay_ps",acceptDelayPs},{"host_unit_bytes",64},{"read_bursts",initiator.readBursts},
            {"write_bursts",initiator.writeBursts},{"peak_pending",initiator.peakPending}}).dump()<<std::endl;
        return 0;
    } catch(const std::exception& e) {std::cerr<<e.what()<<std::endl;return 1;}
}
